type Pair = [string, string];
const E = (arr: Pair[]): Entry[] =>
  arr.map(([t, d], i) => ({ id: i + 1, title: t, description: d }));
const cross = (a: string[], b: string[], fn: (x: string, y: string) => Pair): Pair[] => {
  const o: Pair[] = [];
  for (const x of a) for (const y of b) o.push(fn(x, y));
  return o;
};
const sec = (
  id: string,
  title: string,
  subtitle: string,
  icon: string,
  color: string,
  level: string,
  entries: Entry[],
): Section => ({ id, title, subtitle, icon, color, level, entries });

